Lemma am_finish_g st nu (k : mstate -> optr -> M R) bail ne bb Q :
  (forall st' x, scal st' = (NSLOTS - 1, ac_of (scal st) - 1, shift_of (scal st)) -> x <> None ->
                 gtree E ne bb (k st' x) Q) ->
  0 <= bb ->
  gtree E (S ne) bb (am_finish st nu k bail) Q.
