Theorem malloc_core_g st n :
  SH st -> 0 <= n -> size_overflows n = false ->
  gtree (elen_ok n (pot st + AMC)) EVM (CALLB n (pot st + AMC)) (malloc_core lay_none st n)
        (fun r => snd r <> None /\ pot (fst r) <= pot st + AMC).
